const CATS = { strength: 'Strength', core: 'Core', cardio: 'Cardio', mobility: 'Mobility', sport: 'Swimming & badminton', qigong: 'Qigong', pelvic: 'Pelvic floor – postpartum' };
const EQUIP = { db: 'Dumbbells / water bottles', chair: 'Sturdy chair', band: 'Resistance band', bar: 'Pull-up bar', mat: 'Mat', pool: 'Swimming pool', racket: 'Racket & badminton court' };

export function applyEN(D) {
  for (const e of D.EXERCISES) { const t = X[e.id]; if (!t) continue; [e.name, e.steps, e.breath, e.mistakes, e.safety, e.tips] = t; }
  for (const [k, m] of Object.entries(D.MUSCLES)) { const t = MUS[k]; if (t) [m.name, m.fn, m.life, m.tip] = t; }
  for (const [k, h] of Object.entries(D.HABITS)) { const t = HAB[k]; if (t) [h.name, h.why] = t; }
  for (const f of D.FOODS) { const t = FD[f.id]; if (t) [f.name, f.unit] = t; f.group = GROUPS[f.group] || f.group; }
  for (const m of D.MENUS) m.name = MENU_N[m.name] || m.name;
  for (const l of D.LESSONS) { const t = LES[l.id]; if (t) [l.title, l.body] = t; }
  D.TIPS.splice(0, D.TIPS.length, ...TIPS);
  Object.assign(D.CATS, CATS); Object.assign(D.EQUIP, EQUIP);
}
